import {loadLocale,getLocale,setLocale,translateText,localizeDOM} from './i18n.js';
loadLocale();
import {CARDS,TEAMS,COLORS,STAGES,DIAS,VERSION,cardById,teamName,stageById} from './content.js';
import {createBattle,command,advance,replay,replayRecord,clone,hash} from './engine.js';
import {createArena,arenaCommand,arenaReplay} from './arena.js';
import {freshProfile,loadProfile,saveProfile,parseSave,exportSave,upgrade,recruit,reward,battleConfig,SAVE_KEY} from './profile.js';
const root=document.querySelector('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let loaded;try{loaded=loadProfile()}catch{loaded={profile:freshProfile(),warning:'Browser storage is unavailable. Export your progress before closing.'}}
let profile=loaded.profile,view='command',stage='arrival',battle=null,arena=null,paused=false,speed=1,skillMode=false,replaying=false,replaySource=null,replayIndex=0,filter='all',selectedCard=null,modal=null,arenaTarget=0,storageConflict=false;
const $=s=>document.querySelector(s);function toast(t){$('#toast').textContent=translateText(t);$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){if(storageConflict)throw Error('Another tab changed this profile. Reload before continuing.');try{saveProfile(profile)}catch(e){toast('Progress could not be saved. Export a backup.');throw e}}
function download(name,contents){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([contents],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sound(freq=440){if(!profile?.settings.sound)return;try{const ac=sound.ctx??=new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.15);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.15)}catch{}}
function languageControls(id="language-select"){return `<label class="language-setting">Language <select id="${id}" data-language-select><option value="en" ${getLocale()==='en'?'selected':''}>English</option><option value="ja" ${getLocale()==='ja'?'selected':''}>Japanese (partial; English fallback)</option></select></label>`;}
const tag=(text,cl='')=>`<span class="tag ${cl}">${esc(text)}</span>`;
function nav(){return`<aside class="rail"><a class="brand" href="#" data-action="view" data-value="command"><b>V</b><span>LEGEND<br><strong>WARS</strong></span></a><div class="rail-section">PRESERVATION</div>${[['command','◈','Command'],['missions','▣','Missions'],['collection','▥','V-Cards'],['team','◇','My Sentai'],['exchange','✧','Acquisition'],['archive','⌘','Archive'],['settings','⚙','Save & settings']].map(([id,icon,title])=>`<button class="nav-item ${view===id?'active':''}" data-action="view" data-value="${id}"><span>${icon}</span>${title}</button>`).join('')}<div class="rail-bottom">${languageControls()}<span class="version">BUILD 0.1</span><p>Playable reconstruction<br>Final-state target · 2020</p></div></aside>`}
function top(){return`<header class="top"><div><span class="eyebrow">SUPER SENTAI LEGEND WARS</span><h1>${({command:'Command center',missions:'Mission archive',collection:'V-Card collection',team:'My Sentai',exchange:'Acquisition',archive:'Preservation archive',settings:'Save & settings'})[view]}</h1></div><div class="wallet"><span><i class="mana-dot"></i><b>${profile.mana.toLocaleString()}</b> Mana</span><span><i class="gem-dot"></i><b>${profile.gems.toLocaleString()}</b> V-Gems</span><button class="mode-badge" data-action="view" data-value="settings">${profile.mode==='archive'?'ARCHIVE':'CLASSIC'} MODE</button></div></header>`}
function cardTile(c,handIndex=null){const owned=profile.owned[c.id],inDeck=profile.deck.includes(c.id),isHand=handIndex!==null;return`<button class="vcard ${isHand?'hand-card':''} ${inDeck?'in-deck':''}" style="--card-color:${COLORS[c.color]}" data-action="${isHand?'play':'card'}" data-value="${isHand?handIndex:c.id}" ${isHand&&battle?.result?'disabled':''}><div class="card-top"><span>${c.rarity}</span><b>${c.cost}<small>SOUL</small></b></div><div class="card-emblem"><span>${c.color.slice(0,1).toUpperCase()}</span><small>${esc(teamName(c.team))}</small></div><div class="card-name">${esc(c.name)}</div><div class="card-bottom"><span>${isHand?`[${handIndex+1}]`:inDeck?'IN DECK':owned?'OWNED':'LOCKED'}</span><span>Lv.${owned?.level||1}</span></div></button>`}
function missionCard(st){const locked=profile.mode==='classic'&&st.unlockedBy&&!profile.clears[st.unlockedBy];return`<button class="mission ${stage===st.id?'selected':''}" data-action="select-stage" data-value="${st.id}" ${locked?'disabled':''}><span class="mission-code">${st.chapter}</span><div><span class="eyebrow">${st.kind==='arena'?'COMMAND BATTLE':st.kind==='event'?'ARCHIVE EVENT':'RECONSTRUCTED MISSION'}</span><h3>${st.name}</h3><p>${st.subtitle}</p><span class="reward">${st.reward} Mana · ${st.gems} V-Gems</span></div><span class="mission-status">${locked?'LOCKED':profile.clears[st.id]?'CLEARED ✓':'↗'}</span></button>`}
function intro(){const st=stageById(stage);return`<div class="notice"><span>RECONSTRUCTED BUILD</span> Playable systems and original placeholder art. Historical formulas and content are still being recovered.<button data-action="view" data-value="archive">View evidence ↗</button></div><section class="deployment"><div class="deployment-art"></div><div class="deployment-shade"></div><div class="deployment-top">${tag('MISSION '+st.chapter)}${tag(st.arena?'COMMAND BATTLE':'V-CARD BATTLE')}</div><div class="deployment-copy"><div class="eyebrow">${st.kind==='event'?'LIMITLESS ARCHIVE':st.arena?'HERO ARENA':'DEPLOYMENT READY'}</div><h2>${st.name}</h2><p>${st.subtitle} Assemble your Main Sentai and turn the tide.</p><div class="deployment-actions"><button class="primary" data-action="launch">${profile.pending?'Resume battle':'Deploy Sentai'} <span>→</span></button><button class="glass" data-action="help">How to play</button></div></div><div class="art-note">Original concept artwork · not recovered footage</div></section><div class="section-heading"><h2>Choose your next mission</h2><button class="text-button" data-action="view" data-value="missions">All missions →</button></div><div class="mission-grid">${STAGES.slice(0,3).map(missionCard).join('')}</div><div class="bottom-grid"><div class="panel squad-summary"><div class="section-heading"><h3><span translate="no">${esc(profile.mySentai)}</span></h3><span>${profile.deck.length}/20 cards</span></div><div class="team-stripes">${TEAMS.map(t=>`<div><span>${t.name}</span><strong>${profile.deck.filter(id=>cardById(id).team===t.id).length}</strong></div>`).join('')}</div><button class="text-button" data-action="view" data-value="collection">Manage your deck →</button></div><div class="panel"><span class="eyebrow">YOUR ARCHIVE</span><h3>${Object.keys(profile.clears).length} / 5 missions cleared</h3><p>Progress stays on this device. Export a save to carry it with you.</p><button class="text-button" data-action="export">Export save ↗</button></div></div>`}
function gauge(label,value,max,color){return`<div class="gauge"><div><span>${label}</span><b>${Math.ceil(value).toLocaleString()}<small> / ${max.toLocaleString()}</small></b></div><div class="bar"><i style="width:${Math.max(0,value/max*100)}%;background:${color}"></i></div></div>`}
function battleView(){const st=stageById(battle.config.stage);return`<div class="battle-heading"><div><span class="eyebrow">${replaying?'REPLAY · NO REWARDS':'RECONSTRUCTED V-CARD BATTLE'}</span><h2>${st.name}</h2></div><div class="battle-controls"><span>${Math.floor(battle.tick/600)}:${String(Math.floor(battle.tick/10)%60).padStart(2,'0')}</span><button data-action="speed">${speed}×</button><button data-action="pause">${paused?'Resume':'Pause'}</button><button data-action="retreat">${replaying?'Exit replay':'Retreat'}</button></div></div><section class="battlefield ${profile.settings.reducedMotion?'reduced':''}"><div class="battle-background"></div><div class="battle-overlay"></div><div class="battle-hud"><div class="team-hud"><span class="eyebrow">MAIN SENTAI</span><h3>${teamName(battle.main)}</h3>${gauge('DECK HP',battle.hp,battle.maxHp,'#6cd8ba')}</div><div class="enemy-hud"><span class="eyebrow">${battle.phase==='giant'?'GIANT ENEMY':`WAVE ${battle.wave} / ${st.waves||1}`}</span><h3>${battle.enemy.name}</h3>${gauge('ENEMY HP',battle.enemy.hp,battle.enemy.maxHp,'#ff6259')}</div></div><div class="battle-callout" aria-live="polite">${battle.chain?`CHAIN ×${battle.combo} · Match ${battle.chain.color.toUpperCase()} or ${teamName(battle.chain.team)}`:battle.main?'Your Sentai is fighting.':'Deploy a card to establish your Main Sentai.'}</div><div class="field-slots">${Array.from({length:5},(_,i)=>{const f=battle.fighters[i];return f?`<div class="fighter ${f.hp<=0?'down':''}" style="--card-color:${COLORS[f.card.color]}"><b>${f.card.name}</b><div class="bar"><i style="width:${f.hp/f.maxHp*100}%"></i></div><small>${f.hp<=0?'DOWN':`${f.hp} HP`}</small></div>`:`<div class="fighter empty">${i+1}<small>NOT DEPLOYED</small></div>`}).join('')}</div></section><div class="resource-row">${gauge('SOUL',battle.soul,60,'#70bbff')}${gauge('V-GAUGE',battle.v,100,'#f0cb76')}<button class="action-button" data-action="change" ${battle.change<12||replaying?'disabled':''}>Sentai Change <small>${battle.change}/12 actions</small></button><button class="action-button gold" data-action="finisher" ${battle.v<100||replaying?'disabled':''}>V-Hissatsu <small>Team finisher</small></button></div><div class="section-heading"><div><h3>Your hand <span class="muted">· 1–6 to deploy</span></h3></div><button class="skill-toggle ${skillMode?'on':''}" data-action="skill-mode">${skillMode?'SUPER SKILL ON':'Super Skill'} · 40 V</button></div><div class="hand">${battle.hand.map((id,i)=>cardTile(cardById(id),i)).join('')}</div><div class="battle-footer"><span>Chain by Sentai or color · Space to pause · C to change · F for finisher</span><button class="text-button" data-action="help">Controls</button></div><div class="combat-log"><span class="eyebrow">BATTLE LOG</span>${battle.events.slice(-4).reverse().map(e=>`<div><time>${(e.tick/10).toFixed(1)}s</time>${esc(e.text)}</div>`).join('')}</div>${battle.result?resultModal(battle.result):''}`}
function arenaView(){const f=arena.squad[arena.active];return`<div class="battle-heading"><div><span class="eyebrow">SEPARATE RECONSTRUCTED COMMAND ENGINE</span><h2>Hero Arena · Round ${arena.round}</h2></div><button data-action="arena-exit">Leave Arena</button></div><div class="arena-board"><div><h3>Archive challengers</h3><div class="arena-units">${arena.enemies.map((e,i)=>`<button class="arena-unit ${arenaTarget===i?'targeted':''}" data-action="arena-target" data-value="${i}" ${!e.hp?'disabled':''}><span class="unit-number">0${i+1}</span><h3>${e.name}</h3>${gauge('HP',e.hp,e.maxHp,'#ff6259')}${arenaTarget===i?tag('TARGET'):''}</button>`).join('')}</div></div><div class="arena-divider">VS</div><div class="arena-units">${arena.squad.map((u,i)=>`<div class="arena-unit ${arena.active===i?'active-unit':''}" style="--card-color:${COLORS[u.color]}"><span class="eyebrow">${arena.active===i?'YOUR COMMAND':'SQUAD MEMBER'}</span><h3>${u.name}</h3>${gauge('HP',u.hp,u.maxHp,COLORS[u.color])}<p>Energy ${'◆'.repeat(u.energy)}${'◇'.repeat(3-u.energy)}</p></div>`).join('')}</div></div><div class="arena-actions"><span>${f?.name||'Battle complete'}</span><button class="primary" data-action="arena-action" data-value="strike" ${arena.result||replaying?'disabled':''}>Strike</button><button data-action="arena-action" data-value="guard" ${arena.result||replaying?'disabled':''}>Guard + recover</button><button class="gold" data-action="arena-action" data-value="special" ${arena.result||replaying||f?.energy<2?'disabled':''}>Super · 2 energy</button></div><p class="muted">A separate tactical ruleset. The first three cards in your deck form this placeholder squad; original V-Disc data is not yet recovered.</p><div class="combat-log">${arena.events.slice(-5).reverse().map(x=>`<div>${esc(x)}</div>`).join('')}</div>${arena.result?resultModal(arena.result):''}`}
function resultModal(result){const st=stageById((battle||arena).config.stage);return`<div class="result-layer"><div class="result-box"><span class="eyebrow">${replaying?'ARCHIVED REPLAY':'MISSION RESULT'}</span><h2>${result==='victory'?'VICTORY':result==='retreat'?'WITHDRAWN':'DEFEAT'}</h2><p>${result==='victory'?'Your Sentai held the line.':'Regroup, strengthen your cards, and try again.'}</p>${result==='victory'&&!replaying?`<div class="result-rewards"><div><b>+${st.reward}</b><span>Mana</span></div><div><b>+${st.gems}</b><span>V-Gems</span></div></div>`:''}<button class="primary" data-action="finish">Return to command →</button></div></div>`}
function missions(){return`<p class="page-intro">Five playable reconstruction missions. Archive mode opens every encounter; Classic unlocks the campaign in order.</p><div class="mission-list">${STAGES.map(missionCard).join('')}</div><div class="panel launch-panel"><div><span class="eyebrow">SELECTED MISSION</span><h2>${stageById(stage).name}</h2></div><button class="primary" data-action="launch">Deploy Sentai →</button></div>`}
function collection(){const shown=CARDS.filter(c=>profile.owned[c.id]&&(filter==='all'||c.team===filter));return`<div class="section-heading"><p>${Object.keys(profile.owned).length} / ${CARDS.length} cards · Deck ${profile.deck.length}/20</p><button class="text-button" data-action="reset-deck">Restore starter deck</button></div><div class="filters"><button class="${filter==='all'?'selected':''}" data-action="filter" data-value="all">All Sentai</button>${TEAMS.map(t=>`<button class="${filter===t.id?'selected':''}" data-action="filter" data-value="${t.id}">${t.name}</button>`).join('')}</div><p class="muted">Select a card to train it or change your deck. All card statistics are reconstructed.</p><div class="collection-grid">${shown.map(c=>cardTile(c)).join('')}</div>`}
function team(){return`<div class="panel"><span class="eyebrow">YOUR TEAM</span><h2><span translate="no">${esc(profile.mySentai)}</span></h2><form id="team-name"><label>Squad name <input name="name" value="<span translate="no">${esc(profile.mySentai)}</span>" maxlength="32" required></label><button class="primary" type="submit">Save name</button></form><p class="muted">This name is cosmetic. Main Sentai is established by your first deployment in battle.</p></div><div class="section-heading"><h2>Legend Dia</h2><span>One reconstructed loadout slot</span></div><div class="mission-grid">${DIAS.map(d=>`<div class="panel"><span class="eyebrow">RECONSTRUCTED MODIFIER</span><h3>${d.name}</h3><p>${d.description}</p><button data-action="dia" data-value="${d.id}">${profile.dia===d.id?'Unequip':profile.dias.includes(d.id)?'Equip':`Unlock · ${d.cost} Mana`}</button>${profile.dia===d.id?tag('EQUIPPED','positive'):''}</div>`).join('')}</div>`}
function acquisition(){return`<div class="acquisition-banner"><span class="eyebrow">ARCHIVE RECRUITMENT</span><h2>A new card.<br>A stronger Sentai.</h2><p>Use V-Gems earned in missions. No purchases.</p><button class="primary" data-action="recruit" ${profile.gems<50?'disabled':''}>Recruit · 50 V-Gems →</button><p class="rates">Reconstructed pool: HERO 75% · LEGEND 25%<br>Each of 20 cards in a rarity is equally likely.<br>Duplicates add one copy and grant 60 Mana.</p></div><div class="panel"><h3>Keep progressing</h3><p>Replay any cleared mission to earn Mana and V-Gems. Train cards in your collection and unlock a Legend Dia for your deck.</p><button class="text-button" data-action="view" data-value="missions">Choose a mission →</button></div>`}
function archive(){return`<div class="notice"><span>HONEST PRESERVATION</span>Playable does not mean historically verified.</div><div class="evidence-grid"><div class="panel"><span class="eyebrow">CANONICAL TARGET</span><h2>August 31, 2020</h2><p>Historical final-state behavior is the target. This build uses a separate, explicitly reconstructed ruleset.</p></div><div class="panel"><span class="eyebrow">APK VERIFIED</span><h2>4.2.3 / 110</h2><p>Unity 2018.4.9f1 · ARM64 IL2CPP<br>184 archive entries · 108,058 serialized objects.<br>Final-release status is still unverified.</p></div></div><div class="panel"><h3>What's in this build</h3><table><thead><tr><th>System</th><th>State</th><th>Scope</th></tr></thead><tbody>${[['V-Card battle','Reconstructed','Soul, hand, chaining, Main Sentai, gauges, skills, change, finisher'],['Hero Arena','Reconstructed','Separate command engine; placeholder squad data'],['Content','Reconstructed','40 cards, four Sentai, five encounters, three Dia'],['Progression','Reconstructed','Five training levels, rewards, recruitment, exchanges'],['Presentation','Original placeholders','Generated quarry artwork; symbolic card designs; synthesized cues'],['Historical evidence','Verified / unresolved','Package/runtime verified; rules and full content database unresolved']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel"><h3>Replay your last encounter</h3><p>Replays preserve the starting configuration, seed and commands. V-Card replays animate; Arena replays verify and display the final result. Neither awards rewards.</p><button data-action="replay" ${!profile.lastReplay?'disabled':''}>Play last replay</button> <button data-action="export-replay" ${!profile.lastReplay?'disabled':''}>Export replay</button></div><div class="panel"><h3>Still to recover</h3><p>Native damage and timing formulas, complete master tables, original stage/event definitions, V-Disc data, audiovisual mappings and historical version differences. Original stories, complete modes, co-op, and original 3D animation are not implemented.</p><p class="muted">Ruleset ${VERSION} · ADAPT-001. No values in this game should be cited as original game data.</p></div>`}
function settings(){return`<div class="settings-grid"><div class="panel"><h2>Portable progress</h2><p>Export a save before changing devices or clearing browser storage. Import validates the file and asks before replacing your profile.</p><button class="primary" data-action="export">Export save</button> <button data-action="import">Import save</button><p class="muted">Browser-local profile · format 1 · no account required</p></div><div class="panel"><h2>Play your way</h2>${languageControls("settings-language-select")}<p>Language preference is stored on this device.</p><p>Some Japanese translations are pending. Text inside artwork remains original.</p><label class="setting">Progression policy <select id="mode-select"><option value="archive" ${profile.mode==='archive'?'selected':''}>Archive · all missions accessible</option><option value="classic" ${profile.mode==='classic'?'selected':''}>Classic · sequential campaign</option></select></label><label class="setting"><span>Synthesized sound cues</span><input type="checkbox" id="sound-toggle" ${profile.settings.sound?'checked':''}></label><label class="setting"><span>Reduced motion</span><input type="checkbox" id="motion-toggle" ${profile.settings.reducedMotion?'checked':''}></label><p class="muted">These are reconstruction policies. Combat rules are identical in both modes.</p></div><div class="panel"><h2>Offline and recovery</h2><p id="offline-status">The app caches its playable content after the first successful load. Keep a separate save export.</p><button data-action="recovery-export">Export stored recovery data</button><p class="muted">When moving from a local preview to the hosted game, export and import your profile; each address has its own storage.</p></div></div>`}
function modalView(){if(modal==='help')return`<div class="modal-backdrop"><section class="modal"><button class="close" data-action="close" aria-label="Close">×</button><span class="eyebrow">FIELD MANUAL</span><h2>Assemble your Sentai.</h2><ol><li>Deploy a card from your hand. It establishes your Main Sentai.</li><li>For three seconds, chain another card by the same color or Sentai. The chain bonus grows.</li><li>Main Sentai cards stay and attack automatically. Other teams make an assist attack.</li><li>Use Soul to deploy, and 40 V for a Super Skill. Yellow heals; green restores Soul.</li><li>After 12 actions, Sentai Change clears the field and recovers resources. Deploy a new team.</li><li>At 100 V, V-Hissatsu delivers your team's finisher and revives downed fighters.</li></ol><p>Keyboard: 1–6 deploy · S skill mode · C change · F finisher · Space pause.</p><p class="muted">All numbers above describe this reconstruction, not verified historical mechanics.</p><button class="primary" data-action="close">Ready to deploy</button></section></div>`;
 if(modal==='import')return`<div class="modal-backdrop"><section class="modal"><h2>Replace this profile?</h2><p>The imported profile has ${Object.keys(selectedCard.owned).length} cards and ${selectedCard.gems} V-Gems. Your current save will be downloaded before replacement.</p><button class="primary" data-action="confirm-import">Back up & import</button> <button data-action="close">Cancel</button></section></div>`;
 if(modal==='card'){const c=cardById(selectedCard),o=profile.owned[c.id];return`<div class="modal-backdrop"><section class="modal"><button class="close" data-action="close" aria-label="Close">×</button><span class="eyebrow">${c.rarity} · ${teamName(c.team)} · RECONSTRUCTED</span><h2>${c.name}</h2><div class="card-stats"><div><b>${o.level}</b>LEVEL / 5</div><div><b>${Math.floor(c.attack*(1+(o.level-1)*.07))}</b>ATTACK</div><div><b>${c.cost}</b>SOUL</div><div><b>${o.copies}</b>COPIES</div></div><p><strong>${c.skill}</strong> · ${c.description}</p><button class="primary" data-action="upgrade" data-value="${c.id}" ${o.level>=5||profile.mana<o.level*100?'disabled':''}>${o.level>=5?'Maximum level':`Train · ${o.level*100} Mana`}</button> <button data-action="deck-toggle" data-value="${c.id}">${profile.deck.includes(c.id)?'Remove from deck':'Add to deck'}</button><p class="muted">Deck ${profile.deck.length}/20 · Remove a card before adding a new one. Arena uses your first three deck cards.</p></section></div>`}return''}
function render(){document.documentElement.lang=getLocale();document.title=translateText("Legend Wars · Preservation");if(!profile){root.innerHTML=`<main class="recovery">${languageControls()}<h1>Save recovery</h1><p>${esc(loaded.warning)}</p><button data-action="recovery-export">Export recovery data</button><button data-action="fresh">Start a new profile</button><button data-action="import">Import a save</button></main>`;localizeDOM(root);return}root.innerHTML=`${nav()}<main class="main">${top()}<div class="content">${battle?battleView():arena?arenaView():({command:intro,missions,collection,team,exchange:acquisition,archive,settings}[view])()}</div><footer>Independent preservation build <span>Reconstructed rules · No real-money purchases</span></footer></main>${modalView()}`;localizeDOM(root);}
function arenaRecord(){return{kind:'arena',version:VERSION,config:clone(arena.config),commands:clone(arena.commands),endTick:arena.round,stateHash:hash(arena)}}
function record(){return battle?replayRecord(battle):arenaRecord()}
function checkpoint(){if(!replaying){profile.pending=record();persist()}}
function settle(){if((battle||arena)?.result&&!replaying){reward(profile,record(),(battle||arena).result);persist();sound((battle||arena).result==='victory'?780:180)}}
function launch(){if(profile.pending){const r=profile.pending;if(r.kind==='arena')arena=arenaReplay(r);else{battle=replay(r);if(hash(battle)!==r.stateHash)throw Error('Saved battle failed its replay check.')}}else{const config=battleConfig(profile,stage);if(stageById(stage).arena)arena=createArena(config);else battle=createBattle(config)}paused=false;replaying=false;view='command';checkpoint();render();}
function execute(cmd){if(!battle||replaying)return;if(paused){toast('Resume the battle to issue a command.');return}const r=command(battle,cmd);if(!r.ok)toast(r.error);else{sound(cmd.type==='skill'?650:440);settle();if(!battle.result)checkpoint()}render()}
root.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const a=button.dataset.action,v=button.dataset.value;try{
 if(a==='view'){if(battle||arena){toast('Finish or leave the current encounter first.');return}view=v;modal=null}
 else if(a==='select-stage'){stage=v;toast(`${stageById(v).name} selected`)}
 else if(a==='launch'){launch();return}
 else if(a==='play'){execute({type:skillMode?'skill':'play',slot:Number(v)});return}
 else if(a==='change'||a==='finisher'){execute({type:a});return}
 else if(a==='retreat'){if(replaying){battle=null;replaying=false}else execute({type:'retreat'});}
 else if(a==='pause')paused=!paused;
 else if(a==='speed')speed=speed===1?2:speed===2?4:1;
 else if(a==='skill-mode')skillMode=!skillMode;
 else if(a==='help')modal='help';else if(a==='close')modal=null;
 else if(a==='finish'){battle=null;arena=null;replaying=false;replaySource=null;view='command';modal=null}
 else if(a==='card'){selectedCard=v;modal='card'}else if(a==='filter')filter=v;
 else if(a==='upgrade'){upgrade(profile,v);persist();sound(600)}
 else if(a==='deck-toggle'){if(profile.deck.includes(v))profile.deck=profile.deck.filter(id=>id!==v);else{if(profile.deck.length>=20)throw Error('Remove one card first; your deck already has 20.');profile.deck.push(v)}persist()}
 else if(a==='reset-deck'){profile.deck=CARDS.filter(c=>c.rarity==='HERO').map(c=>c.id);persist();toast('Starter deck restored')}
 else if(a==='recruit'){const c=recruit(profile);persist();selectedCard=c.id;modal='card';sound(880);toast(`${c.rarity} · ${c.name}`)}
 else if(a==='dia'){const d=DIAS.find(x=>x.id===v);if(!profile.dias.includes(v)){if(profile.mana<d.cost)throw Error('Not enough Mana.');profile.mana-=d.cost;profile.dias.push(v)}profile.dia=profile.dia===v?null:v;persist()}
 else if(a==='export'){download('legend-wars-save.json',exportSave(profile));toast('Save exported')}
 else if(a==='import')$('#import-file').click();
 else if(a==='confirm-import'){if(profile)download('legend-wars-before-import.json',exportSave(profile));profile=clone(selectedCard);persist();modal=null;view='command';toast('Save imported')}
 else if(a==='recovery-export'){download('legend-wars-recovery.json',JSON.stringify({current:localStorage.getItem(SAVE_KEY),backup:localStorage.getItem(SAVE_KEY+'-backup')}));}
 else if(a==='fresh'){profile=freshProfile();persist()}
 else if(a==='arena-target')arenaTarget=Number(v);
 else if(a==='arena-action'){const r=arenaCommand(arena,v,arenaTarget);if(!r.ok)throw Error(r.error);if(arena.enemies[arenaTarget].hp<=0)arenaTarget=Math.max(0,arena.enemies.findIndex(x=>x.hp>0));settle();if(!arena.result)checkpoint();sound(500)}
 else if(a==='arena-exit'){if(!replaying){arena.result='retreat';settle()}arena=null;replaying=false;}
 else if(a==='export-replay')download('legend-wars-replay.json',JSON.stringify(profile.lastReplay,null,2));
 else if(a==='replay'){const r=profile.lastReplay;replaying=true;view='command';if(r.kind==='arena')arena=arenaReplay(r);else{const verified=replay(r);if(hash(verified)!==r.stateHash)throw Error('Replay verification failed');battle=createBattle(r.config);replaySource=r;replayIndex=0;paused=false}}
 render();
 }catch(err){toast(err.message);render()}});
root.addEventListener('submit',e=>{if(e.target.id!=='team-name')return;e.preventDefault();profile.mySentai=new FormData(e.target).get('name').trim().slice(0,32)||'Archive squad';persist();render();toast('Squad name saved')});
root.addEventListener('change',e=>{if(e.target.hasAttribute('data-language-select')){setLocale(e.target.value);render();return;}if(e.target.id==='mode-select')profile.mode=e.target.value;else if(e.target.id==='sound-toggle')profile.settings.sound=e.target.checked;else if(e.target.id==='motion-toggle')profile.settings.reducedMotion=e.target.checked;else return;persist();sound();render()});
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Save file is too large');selectedCard=parseSave(await f.text());if(!profile){profile=selectedCard;persist();render()}else{modal='import';render()}}catch(err){toast(err.message)}finally{e.target.value=''}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||modal||!battle)return;if(e.code==='Space'){e.preventDefault();paused=!paused;render()}else if(/^[1-6]$/.test(e.key))execute({type:skillMode?'skill':'play',slot:Number(e.key)-1});else if(e.key.toLowerCase()==='c')execute({type:'change'});else if(e.key.toLowerCase()==='f')execute({type:'finisher'});else if(e.key.toLowerCase()==='s'){skillMode=!skillMode;render()}});
setInterval(()=>{if(!battle||battle.result||paused||modal||document.hidden||storageConflict)return;try{for(let i=0;i<speed&&!battle.result;i++){if(replaying){while(replayIndex<replaySource.commands.length&&replaySource.commands[replayIndex].tick===battle.tick)command(battle,replaySource.commands[replayIndex++]);if(battle.tick>=replaySource.endTick){paused=true;break}}advance(battle)}settle();if(!battle.result&&battle.tick%50===0)checkpoint();render()}catch(err){paused=true;toast(err.message)}},100);
window.addEventListener('storage',e=>{if(e.key===SAVE_KEY){storageConflict=true;paused=true;toast('This profile changed in another tab. Reload to continue safely.')}});
window.addEventListener('beforeunload',()=>{if(profile&&(battle||arena)&&!(battle||arena).result&&!replaying&&!storageConflict)try{checkpoint()}catch{}});
render();if(loaded.warning)toast(loaded.warning);else if(profile)try{persist()}catch{}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline installation unavailable. The game still works online.'));
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_game_state',description:'Read profile and current battle state without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view,mana:profile?.mana,gems:profile?.gems,battle:battle?{tick:battle.tick,hp:battle.hp,soul:battle.soul,result:battle.result}:null})});document.modelContext.registerTool({name:'deploy_hand_card',description:'Play a numbered hand card in the active unpaused V-Card battle.',inputSchema:{type:'object',properties:{slot:{type:'integer',minimum:0,maximum:5}},required:['slot'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.slot)||input.slot<0||input.slot>5||!battle||paused||replaying)throw Error('An active unpaused battle and valid slot are required.');const r=command(battle,{type:'play',slot:input.slot});if(!r.ok)throw Error(r.error);settle();if(!battle.result)checkpoint();render();return{played:true,tick:battle.tick,soul:battle.soul}}})}catch{}}
